start() {
  if (this.#start) {
    return this.#start;
  }
  this.#start = (async () => {
    if (this.parent) {
      this.parent.childEvents.push(this);
    }
    game.getGlobalHistory("everything").push(this);
    this.manager.setStatusEvent(this, true);
    await this.loop().then(() => {
      this.manager.popStatusEvent();
    });
  })();
  return this.#start;
}

async loop() {
  const trigger = async (trigger2, to) => {
    this._triggered = to;
    if (this.type == "card") {
      await this.trigger("useCardTo" + trigger2);
    }
    await this.trigger(this.name + trigger2);
  };
  if (await this.checkSkipped()) {
    return;
  }
  while (true) {
    await this.waitNext();
    if (!this.finished) {
      if (this._triggered === 0) {
        await trigger("Before", 1);
      } else if (this._triggered === 1) {
        await trigger("Begin", 2);
      } else {
        this.#inContent = true;
        let next = this.content(this).catch((error) => {
          if (lib.config.ignore_error || _status.connectMode && !lib.config.debug) {
            game.print("游戏出错：" + this.name);
            game.print(error.toString());
            console.error(error);
          } else {
            throw error;
          }
        });
        await next.finally(() => this.#inContent = false);
      }
    } else {
      if (this._triggered === 1) {
        await trigger("Omitted", 4);
      } else if (this._triggered === 2) {
        await trigger("End", 3);
      } else if (this._triggered === 3) {
        await trigger("After", 4);
      } else if (this.after.length) {
        this.next.push(this.after.shift());
      } else {
        return;
      }
    }
  }
}

waitNext() {
  if (this.#waitNext) {
    return this.#waitNext;
  }
  this.#waitNext = (async () => {
    let result;
    while (true) {
      await _status.pauseManager.waitPause();
      if (this.manager.tempEvent) {
        if (this.manager.tempEvent === this) {
          this.manager.tempEvent = void 0;
        } else {
          this.cancel(true, null, "notrigger");
          return result;
        }
      }
      if (!this.next.length) {
        return result;
      }
      const next = this.next[0];
      await next.start();
      if (next.result) {
        result = next.result;
      }
      this.next.shift();
    }
  })().finally(() => this.#waitNext = void 0);
  return this.#waitNext;
}

then(onfulfilled, onrejected) {
  return (this.parent ? this.parent.waitNext().then(() => void 0) : this.start()).then(onfulfilled, onrejected);
}

async forResult() {
  await this;
  return this.result;
}

#step = 0;
#nextStep = null;
/**
 * 最后一个子事件的result
 */
_result = {};
get step() {
  return this.#step;
}
set step(num) {
  this.#nextStep = num;
}
updateStep() {
  if (this.#nextStep === null) {
    return;
  }
  this.#step = this.#nextStep;
  this.#nextStep = null;
}

compile(content) {
  if (!Array.isArray(content)) {
    throw new ReferenceError("content必须是一个数组");
  }
  const compiler = this;
  return async function(event) {
    if (!Number.isInteger(event.step)) {
      event.step = 0;
    }
    while (!event.finished) {
      if (event.step >= content.length) {
        event.finish();
        break;
      }
      compiler.beforeExecute(event);
      event.step++;
      let result;
      if (!compiler.isPrevented(event)) {
        const original = content[event.step];
        result = await Reflect.apply(original, this, [event, event._trigger, event.player, event._result]);
      }
      const nextResult = await event.waitNext();
      event._result = result ?? nextResult ?? event._result;
      compiler.afterExecute(event);
    }
  };
}

if (info.singleCard) {
  next._targets = next.targets.slice(0);
  next.target = next.targets[0];
  next.addedTargets = next.targets.splice(1);
  if (next.addedTargets.length) {
    next.addedTarget = next.addedTargets[0];
  }
}
